interface.signature:
interface DigestRecommendation {
  id: string;
  title: string;
  summary: string;
  impactLevel: 'HIGH' | 'MEDIUM' | 'LOW';
  dashboardUrl: string;
}

interface WeeklyDigestEmailProps {
  userName: string;
  businessName: string;
  recommendations: DigestRecommendation[];
  conversionTrend: { thisWeek: number; lastWeek: number; change: number } | null;
  implementationWins: { title: string; improvement: string }[];
  unsubscribeUrl: string;
}

interface EmailPreferencesInput {
  emailNotificationsEnabled: boolean;
  emailDigestFrequency: 'weekly' | 'off';
  timezone: string; // max 50 chars
}

type ActionResult = { success: true } | { success: false; error: string };

export async function updateEmailPreferences(data: EmailPreferencesInput): Promise<ActionResult>

resend.emails.send({
  from: 'MetricFortune Insights <insights@metricfortune.app>',
  to: user.email,
  subject: `Your ${recommendations.length} optimization opportunities this week`,
  react: WeeklyDigestEmail({ userName, businessName, recommendations, conversionTrend, implementationWins, unsubscribeUrl }),
})

// Published from session aggregation job when conversion rate drops >20% WoW
await inngest.send({
  name: 'metrics/significant-change',
  data: { businessId: string; siteId: string; metric: string; change: number; userId: string }
})

// Consumed by metricChangeNotifyJob in src/inngest/metric-change-notify.ts

model User {
  // ... existing fields ...
  emailNotificationsEnabled Boolean   @default(true)
  emailDigestFrequency      String    @default("weekly") // "weekly" | "off"
  emailUnsubscribeToken     String?   @unique
  timezone                  String    @default("UTC")
  lastDigestSentAt          DateTime?

  @@index([emailUnsubscribeToken])
}
